using namespace std;

#define ll long long
#define vi vector<int>
#define pii pair<int, int>
#define vii vector<pii>


const int N = 505010;
const int MOD = 1e9 + 7;

vi g[3 * N];
int cost1[3 * N], cost2[3 * N];
int tree[4 * N], pos[4 * N], a[N], c[N];
int nxtL[N], nxtR[N];
int num[N];
int n, q;

void build(int v, int tl, int tr) {
    if (tl == tr) {
        tree[v] = a[tl];
        pos[v] = tl;
        return;
    }
    int tm = (tl + tr) / 2;
    build(v * 2, tl, tm);
    build(v * 2 + 1, tm + 1, tr);
    if (tree[v * 2] > tree[v * 2 + 1]) {
        tree[v] = tree[v * 2];
        pos[v] = pos[v * 2];
    }
    else {
        tree[v] = tree[v * 2 + 1];
        pos[v] = pos[v * 2 + 1];
    }
}

pii getmax(int v, int tl, int tr, int l, int r) {
    if (l > r) return { -1, -1 };
    if (l == tl && r == tr) {
        return { tree[v], pos[v] };
    }
    int tm = (tl + tr) / 2; 
    pii tmp = max(getmax(v * 2, tl, tm, l, min(r, tm)), getmax(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r));
    return tmp;
}


int state = -1;
ll ans;

void addEdge(int v, int u) {
    if (v == -1 || u == -1) return;
    g[v].push_back(u);
}

int it = 0;

int precalc(int l, int r, int minc) {
    int xx = minc;
    state++;
    int vres = state;
    if (l > r) return vres;
    pii p = getmax(1, 0, n - 1, l, r);

    vi t;

    int pos = p.second;
    while (pos >= l) {
        t.push_back(pos);
        pos = nxtL[pos];
    }

    reverse(t.begin(), t.end());

    pos = nxtR[p.second];
    while (pos <= r) {
        t.push_back(pos);
        pos = nxtR[pos];
    }

    for (int x : t) minc = min(minc, c[x]);
    for (int x : t) num[x] = vres;
    if (xx <= (int)1e9) ans += minc;

    cost1[vres] = minc;

    ans += 1ll * minc * ((int)t.size() - 1);
    addEdge(vres, precalc(l, t[0] - 1, minc));

    for (int i = 1; i < t.size(); i++) {
        addEdge(vres, precalc(t[i - 1] + 1, t[i] - 1, minc));
    }

    addEdge(vres, precalc(t.back() + 1, r, minc));

    for (int v : t) num[v] = vres;
    return vres;
}

void go(int v) {
    if (!cost1[v]) return;
    if (!g[v].size()) return;
    if (v == 1) ans -= 1ll * ((int)g[v].size() - 2) * cost1[v];
    else ans -= 1ll * ((int)g[v].size() - 1) * cost1[v];
    cost1[v] = 0;
    for (int u : g[v]) {
        go(u);
    }


}

void solve() {
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> c[i];
    vi p(n);
    for (int i = 0; i < n; i++) cin >> p[i], p[i]--;
    map <int, int> lst;
    for (int i = 0; i < n; i++) {
        if (lst.find(a[i]) == lst.end()) nxtL[i] = -1;
        else nxtL[i] = lst[a[i]];
        lst[a[i]] = i;
    }
    lst.clear();
    for (int i = n - 1; i >= 0; i--) {
        if (lst.find(a[i]) == lst.end()) nxtR[i] = n;
        else nxtR[i] = lst[a[i]];
        lst[a[i]] = i;
    }

    build(1, 0, n - 1);
    for (int i = 0; i <= 3 * n; i++) g[i].clear();
    ans = 0;
    state = 0;
    int root = precalc(0, n - 1, (int)1e9 + 1);
    cout << ans << " ";

    for (int i = 0; i < n; i++) {
        int j = num[p[i]];
        go(j);
        cout << ans << " ";
    }

    cout << "\n";
}

int main()
{
    int T = 1;
    cin >> T;
    while (T--) {
        solve();
    }
    return 0;
}

#include <bits/stdc++.h>

using std::cin;
using std::cout;
using vi = std::vector<int>;
using vvi = std::vector<vi>;
using ll = long long;

const auto ready = []()
    {
        cin.tie(0);
        std::ios_base::sync_with_stdio(false);
        return true;
    }();

ll binpow(ll a, ll p, ll mod)
{
    ll res = 1;
    ll mult = a;
    while (p) {
        if (p & 1) res = res * mult % mod;
        mult = mult * mult % mod;
        p >>= 1;
    }
    return res;
}

const ll mod = 998244353;
const int max_a = 2e5 + 10;
const int max_len = 6;
vi fi_div(max_a);
vi num_len(max_a);

void precalc() {
    // Here we precompute the number of unique primes in each number, i.e. w(n)
    for (int i = 2; i < max_a; ++i) {
        if (fi_div[i] == 0) {
            for (int j = i; j < max_a; j += i) {
                if (fi_div[j] == 0) fi_div[j] = i;
            }
        }
    }

    for (int i = 2; i < max_a; ++i) {
        int x = i;
        int len = 0;
        while (x > 1) {
            ++len;
            int tmp = fi_div[x];
            while (fi_div[x] == tmp) x /= tmp;
        }
        num_len[i] = len;
    }
}

void solve() {
    int n, k;
    cin >> n >> k;

    vi vec(n);
    for(int i = 0; i < n; ++i) cin >> vec[i];

    vvi cnt(n + 1, vi(max_len + 1));

    for(int i = 0; i < n; ++i) {
        int x = vec[i];
        cnt[vec[i]][num_len[x]] += 1;
    }

    // Here we calcualte auxilary dp - cnt[x][len] - how many numbers with w(n) = len are divisible by x
    for (int i = 1; i < n + 1; ++i) {
        vi dp(max_len + 1);

        for (int j = i; j < n + 1; j += i) {
            for(int s =0 ; s < max_len + 1; ++s) dp[s] += cnt[j][s];
        }
        cnt[i] = dp;
    }

    vvi dp(n + 1, vi(2 * max_len + 1));
    ll ans = 0LL;

    // Here we calcualte dp[g][len]
    for (int g = n; g >= 1; --g) {
        // Account for cases len_a != len_b
        for (int len1 = 0; len1 <= max_len; ++len1) {
            for (int len2 = len1 + 1; len2 <= max_len; ++len2) {
                dp[g][len1 + len2] += 1LL * cnt[g][len1] * cnt[g][len2] % mod;
                dp[g][len1 + len2] %= mod;
            }
        }
        // Account for cases len_a = len_b
        for (int len = 0; len <= max_len; ++len) {
            dp[g][len + len] += 1LL * cnt[g][len] * (cnt[g][len] - 1) / 2 % mod;
            dp[g][len + len] %= mod;
        }

        // Subtruct states with where gcd is multiple of current g
        for (int j = 2 * g; j < n + 1; j += g) {
            for(int s = 0; s < 2 * max_len + 1; ++s) {
                dp[g][s] -= dp[j][s];
                dp[g][s] %= mod;
            }
        }

        for(int s = 0; s <  2 * max_len + 1; ++s) {
            dp[g][s] %= mod;
            dp[g][s] += mod;
            dp[g][s] %= mod;
        }

        // Add k-th powers to the answer
        int gcd_len = num_len[g];
        for (int len = 0; len < 2 * max_len + 1; ++len) {
            int rad = len - gcd_len;
            ans += dp[g][len] % mod * binpow(rad, k, mod) % mod;
            ans %= mod;
        }

    }
    cout << ans << "\n";
}

int main()
{
    precalc();
    int t;
    cin >> t;
    while (t--) solve();
    return 0;
}
